const svg = root.querySelector('.m-mgb-svg');
let tx = 180, ty = 135, cx = 180, cy = 135, vx = 0, vy = 0, manual = false, raf = 0, last = performance.now();

const onMove = e => {
  manual = true;
  const r = svg.getBoundingClientRect();
  if (!r.width || !r.height) return;
  tx = ((e.clientX - r.left) / r.width) * 360;
  ty = ((e.clientY - r.top) / r.height) * 270;
};
const onLeave = () => { manual = false; };
root.addEventListener('pointermove', onMove);
root.addEventListener('pointerleave', onLeave);

function tick(now) {
  if (!root.isConnected) return;
  const dt = Math.min(0.032, (now - last) / 1000);
  last = now;
  const t = now * 0.0011;
  circles[0].setAttribute('cx', (180 + Math.sin(t * 0.7) * 14).toFixed(1));
  circles[0].setAttribute('cy', (135 + Math.cos(t * 0.6) * 10).toFixed(1));
  circles[1].setAttribute('cx', (180 + Math.cos(t * 1.1) * 62).toFixed(1));
  circles[1].setAttribute('cy', (135 + Math.sin(t * 1.3) * 44).toFixed(1));
  circles[2].setAttribute('cx', (180 + Math.sin(t * 0.9 + 2.1) * 68).toFixed(1));
  circles[2].setAttribute('cy', (135 + Math.cos(t * 1.1 + 1.2) * 48).toFixed(1));
  circles[3].setAttribute('cx', (180 + Math.cos(t * 1.4 + 4.0) * 52).toFixed(1));
  circles[3].setAttribute('cy', (135 + Math.sin(t * 0.8 + 3.1) * 54).toFixed(1));
  circles[4].setAttribute('cx', (180 + Math.sin(t * 1.2 + 5.0) * 58).toFixed(1));
  circles[4].setAttribute('cy', (135 + Math.cos(t * 1.0 + 4.4) * 36).toFixed(1));

  if (!manual) {
    tx = 180 + Math.cos(t * 0.85) * 76;
    ty = 135 + Math.sin(t * 1.55) * 42;
